class CustomFewShotMethod(FewShotClassifier):
    """CAPT: Cross-Attention Prototypical Networks with Adaptive feature Transform.
    Novel: cross-attention over prototypes, adaptive scale/shift from proto stats,
    learnable hybrid of cosine + L2 with temperature scaling.
    """
    def __init__(self):
        backbone = make_backbone(use_pooling=True)
        super().__init__(backbone=backbone, use_softmax=False)
        self.capt = _CAPTModule(FEATURE_DIMENSION)
    def process_support_set(self, support_images: Tensor, support_labels: Tensor):
        self.compute_prototypes_and_store_support_set(support_images, support_labels)
    def forward(self, query_images: Tensor) -> Tensor:
        qf = self.compute_features(query_images)
        return self.capt(qf, self.prototypes, self.cosine_distance_to_prototypes,
                         self.l2_distance_to_prototypes, self.softmax_if_specified)
    @staticmethod
    def is_transductive() -> bool:
        return False
    def compute_loss(self, scores: Tensor, labels: Tensor) -> Tensor:
        return F.cross_entropy(scores, labels)
